package May2021PrepLeetcode;

import java.util.LinkedList;
import java.util.Queue;

public class _0117PopulatingNextRightPointersInEachNodeII {
	public static class Node {
		public int val;
		public Node left;
		public Node right;
		public Node next;

		public Node() {
		}

		public Node(int _val) {
			val = _val;
		}

		public Node(int _val, Node _left, Node _right, Node _next) {
			val = _val;
			left = _left;
			right = _right;
			next = _next;
		}
	};

	public static void main(String[] args) {
		Node tn = new Node(1);
		tn.left = new Node(2);
		tn.left.left = new Node(4);
		tn.left.right = new Node(5);
		tn.right = new Node(3);
		// tn.right.left = new Node(6);
		tn.right.right = new Node(7);
		printNodes(connect(tn));
	}

	public static void printNodes(Node n) {
		if (n != null) {
			printNodes(n.left);
			printNodes(n.right);
			if (n.next != null) {
				System.out.println(n.val + "->" + n.next.val);
			} else {
				System.out.println(n.val + "->null");
			}
		}
	}

	public static Node connect(Node root) {
		if (root == null)
			return root;

		Queue<Node> q = new LinkedList<Node>();
		q.offer(root);
		while (!q.isEmpty()) {
			int size = q.size();
			Node prev = null;
			for (int i = 0; i < size; i++) {
				Node curr = q.poll();

				curr.next = prev;
				prev = curr;

				if (curr.right != null) {
					q.offer(curr.right);
				}

				if (curr.left != null) {
					q.offer(curr.left);
				}
			}
		}
		return root;
	}

}

